#include <iostream>
#include <iomanip>
using namespace std;
int main() {
    double V, G, M, N;
    scanf("%lf%lf%lf%lf", &V, &G, &M, &N);
    double P_V = V / 2.0;
    double P_G = (G < 300) ? M : N;
    double result = (P_V < P_G) ? P_V : P_G;
    printf("%.1f\n", result);
    return 0;
}

